fn list_deep_clone(arr: &Vec<u64>) -> Vec<u64> {
    // Pre-allocate a new vector with the same length as the input
    let mut copied = Vec::with_capacity(arr.len());

    // Copy each element from the input into the new vector
    for &value in arr.iter() {
        copied.push(value);
    }

    // Return the newly built deep clone
    copied
}

